def calculate_age(current_year, birth_year):
    return current_year - birth_year

print(calculate_age(1995, 2025))

def describe(city, country):
    return city + ', ' + country

print(describe(country='Türkiye', city='İzmir'))

def is_even(n):
    if n % 2 == 0:
        return True
    return False

print(is_even(10))
print(is_even(7))

def passed_scores(scores):
    result = []
    for s in scores:
        if s >= 50:
            result.append(s)
    return result, len(result)

notes = [72, 45, 90, 38, 65]
print(passed_scores(notes))
passed, count = passed_scores(notes)
print(passed, count)

def first_negative(numbers):
    for n in numbers:
        if n < 0:
            return n
        return None

print(first_negative([4, -2, 7, -9]))

