def show_args(**info):
    print(type(info), len(info))
    for key, value in info.items():
        print(' *', key, '=', value)

show_args(name='Alice', age=30, city='İstanbul')

def order(dish, *extras, **notes):
    print(dish, extras, notes)

order('pide', 'ayran', 'salata', spicy=True)

def square_number(n):
    return n ** 2

def apply(f, x):
    return f(x)

print(apply(square_number, 3))
print(apply(len, 'Python'))

def shout(text):
    return text.upper() + '!'

def whisper(text):
    return text.lower() + '...'

def speak(style, text):
    return style(text)

print(speak(whisper, 'Merhaba DÜNYA'))
